const demoLessons = <Lesson>[
  Lesson(id:'l1',chapterId:'m1',title:'Les nombres entiers',summary:'Lire, écrire et comparer les nombres entiers.',content:'Un nombre entier est un nombre sans partie décimale. Exemples : 0, 1, 25, 100 et 2 026. Pour comparer deux entiers, on compare d’abord leur nombre de chiffres. S’ils ont le même nombre de chiffres, on compare les chiffres de gauche à droite. Sur une droite graduée, le nombre situé le plus à droite est le plus grand.',keyPoints:['Un entier n’a pas de partie décimale.','La position sur une droite graduée permet de comparer les nombres.','Le signe < signifie « inférieur à » et le signe > signifie « supérieur à ».']),
  Lesson(id:'l2',chapterId:'m1',title:'Les nombres décimaux',summary:'Lire et écrire les nombres avec une virgule.',content:'Un nombre décimal possède une partie entière et une partie décimale séparées par une virgule. Dans 12,45, 12 est la partie entière, 4 représente les dixièmes et 5 les centièmes. Pour comparer deux nombres décimaux, on compare les parties entières puis les chiffres des dixièmes, des centièmes et ainsi de suite.',keyPoints:['La virgule sépare la partie entière de la partie décimale.','Le premier chiffre après la virgule indique les dixièmes.','On peut ajouter des zéros à droite sans changer la valeur : 2,5 = 2,50.']),
  Lesson(id:'l3',chapterId:'m2',title:'Addition et soustraction',summary:'Poser et effectuer une addition ou une soustraction.',content:'Pour additionner ou soustraire des nombres décimaux, on aligne les virgules. On complète si nécessaire avec des zéros, puis on calcule colonne par colonne. On place la virgule du résultat sous les autres virgules.',keyPoints:['Toujours aligner les virgules.','Vérifier le résultat par un calcul inverse lorsque c’est possible.']),
  Lesson(id:'l4',chapterId:'m2',title:'Multiplication',summary:'Comprendre la multiplication comme addition répétée.',content:'Multiplier un nombre par un autre revient à additionner plusieurs fois le même nombre. Exemple : 4 × 3 = 3 + 3 + 3 + 3 = 12. Pour poser une multiplication, on effectue les produits en respectant les rangs.',keyPoints:['Les facteurs sont les nombres que l’on multiplie.','Le produit est le résultat de la multiplication.']),
  Lesson(id:'l5',chapterId:'m3',title:'Mesurer une longueur',summary:'Utiliser les unités de longueur.',content:'L’unité principale de longueur est le mètre (m). On utilise aussi le kilomètre (km), le centimètre (cm) et le millimètre (mm). 1 km = 1 000 m ; 1 m = 100 cm ; 1 cm = 10 mm. Avant de calculer, il faut convertir les mesures dans la même unité.',keyPoints:['Choisir une unité adaptée à l’objet mesuré.','Convertir dans la même unité avant une addition ou une soustraction.']),
  Lesson(id:'l6',chapterId:'m3',title:'Le périmètre',summary:'Calculer le contour d’une figure.',content:'Le périmètre est la longueur totale du contour d’une figure. Pour un rectangle, P = 2 × (longueur + largeur). Pour un carré de côté c, P = 4 × c. Le résultat s’exprime dans une unité de longueur.',keyPoints:['Le périmètre mesure un contour.','Toutes les longueurs doivent être exprimées dans la même unité.']),
  Lesson(id:'l7',chapterId:'f1',title:'Comprendre un texte',summary:'Repérer le thème, les personnages et les informations.',content:'Pour comprendre un texte, on lit d’abord le titre et le texte en entier. On identifie ensuite qui fait l’action, où et quand se déroule la scène, puis on repère les informations importantes. Une réponse de compréhension doit s’appuyer sur le texte.',keyPoints:['Lire le texte entièrement avant de répondre.','Justifier une réponse avec un indice du texte.']),
  Lesson(id:'l8',chapterId:'f1',title:'Le vocabulaire en contexte',summary:'Comprendre un mot grâce à la phrase.',content:'Un mot peut avoir plusieurs sens. Pour comprendre un mot inconnu, on observe les mots qui l’entourent, le sujet du texte et la phrase entière. On peut ensuite vérifier le sens dans un dictionnaire.',keyPoints:['Le contexte aide à comprendre un mot.','Le dictionnaire donne la définition et parfois plusieurs sens.']),
  Lesson(id:'l9',chapterId:'f2',title:'La phrase et ses types',summary:'Reconnaître une phrase et ses types.',content:'Une phrase commence par une majuscule et se termine par un signe de ponctuation. La phrase déclarative donne une information, la phrase interrogative pose une question, la phrase exclamative exprime une émotion et la phrase impérative donne un ordre ou un conseil.',keyPoints:['Une phrase commence par une majuscule.','Les principaux types sont déclaratif, interrogatif, exclamatif et impératif.']),
  Lesson(id:'l10',chapterId:'f2',title:'Le sujet et le verbe',summary:'Identifier le sujet et le verbe.',content:'Le verbe exprime généralement une action ou un état. Le sujet indique de qui ou de quoi on parle. Pour trouver le sujet, on peut poser la question « qui est-ce qui ? » ou « qu’est-ce qui ? » devant le verbe.',keyPoints:['Le verbe se conjugue.','Le sujet commande souvent l’accord du verbe.']),
  Lesson(id:'l11',chapterId:'s1',title:'Les êtres vivants',summary:'Distinguer les êtres vivants des objets non vivants.',content:'Un être vivant naît, se nourrit, grandit, se reproduit et meurt. Les animaux et les végétaux sont des êtres vivants. Une pierre ou une table ne réalise pas l’ensemble de ces fonctions.',keyPoints:['Les êtres vivants réalisent des fonctions vitales.','Les végétaux sont aussi des êtres vivants.']),
  Lesson(id:'l12',chapterId:'s1',title:'Les besoins des plantes',summary:'Découvrir les conditions nécessaires à la vie des plantes.',content:'Pour se développer, une plante verte a besoin d’eau, de lumière, d’air et de sels minéraux présents dans le sol. Une expérience doit faire varier un seul facteur à la fois pour comprendre son rôle.',keyPoints:['L’eau et la lumière sont indispensables au développement d’une plante verte.','Une expérience compare des situations dans des conditions précises.']),
  Lesson(id:'l13',chapterId:'s2',title:'L’hygiène et la santé',summary:'Adopter des gestes simples pour rester en bonne santé.',content:'L’hygiène aide à prévenir certaines maladies. Se laver régulièrement les mains avec de l’eau propre et du savon, boire de l’eau potable, manger varié, dormir suffisamment et garder son environnement propre sont des habitudes importantes.',keyPoints:['Se laver les mains réduit la transmission de microbes.','L’eau potable et une alimentation variée contribuent à la santé.']),
  Lesson(id:'l14',chapterId:'s2',title:'Les organes des sens',summary:'Découvrir les cinq sens.',content:'Les cinq sens sont la vue, l’ouïe, l’odorat, le goût et le toucher. Les organes associés sont les yeux, les oreilles, le nez, la langue et la peau. Ils permettent de recevoir des informations sur notre environnement.',keyPoints:['Les cinq sens nous renseignent sur notre environnement.','Il faut protéger ses organes sensoriels.']),
  Lesson(id:'l15',chapterId:'h1',title:'Le temps historique',summary:'Utiliser les dates et les repères chronologiques.',content:'L’histoire étudie les sociétés humaines du passé. Une date permet de situer un événement. Une frise chronologique représente les événements dans l’ordre, du plus ancien au plus récent.',keyPoints:['La chronologie classe les événements dans le temps.','Une frise se lit de gauche à droite dans l’ordre chronologique habituel.']),
  Lesson(id:'l16',chapterId:'h1',title:'Les siècles et les années',summary:'Se repérer avec les siècles.',content:'Un siècle dure 100 ans. Le 1er siècle va de l’an 1 à l’an 100. Le 20e siècle va de 1901 à 2000. Pour déterminer le siècle d’une année, on peut regrouper les années par périodes de cent ans.',keyPoints:['Un siècle compte 100 ans.','Le 21e siècle va de 2001 à 2100.']),
  Lesson(id:'l17',chapterId:'h2',title:'Les continents et les océans',summary:'Nommer les grandes divisions de la Terre.',content:'La Terre comporte six continents généralement enseignés dans de nombreux programmes : Afrique, Amérique, Asie, Europe, Océanie et Antarctique. Les grands océans sont Pacifique, Atlantique, Indien, Austral et Arctique.',keyPoints:['L’Afrique est un continent.','Les océans couvrent une grande partie de la surface terrestre.']),
  Lesson(id:'l18',chapterId:'h2',title:'Lire un plan et une carte',summary:'Utiliser le titre, la légende et les directions.',content:'Une carte représente un espace à une échelle réduite. Pour la lire, on observe son titre, sa légende, l’échelle et l’orientation. Les points cardinaux sont le nord, le sud, l’est et l’ouest.',keyPoints:['La légende explique les symboles de la carte.','La rose des vents indique les directions.']),
  Lesson(id:'l19',chapterId:'a1',title:'Greetings and introductions',summary:'Saluer et se présenter en anglais.',content:'In English, we can say: Hello! / Good morning! to greet someone. To introduce yourself, say: My name is Ama. I am a student. To ask someone’s name, say: What is your name? Be polite and listen to the answer.',keyPoints:['Hello = Bonjour.','My name is… = Je m’appelle…','What is your name? = Comment t’appelles-tu ?']),
  Lesson(id:'l20',chapterId:'a1',title:'Asking how someone is',summary:'Demander et dire comment on va.',content:'To ask how someone is, say: How are you? Possible answers include: I am fine, thank you. And you? / I am well. Remember to use please and thank you to be polite.',keyPoints:['How are you? = Comment vas-tu ?','I am fine, thank you. = Je vais bien, merci.']),
  Lesson(id:'l21',chapterId:'a2',title:'Classroom objects',summary:'Nommer quelques objets de la classe.',content:'Useful words: a book (un livre), a pen (un stylo), a pencil (un crayon), a ruler (une règle), a bag (un sac), a desk (un bureau). Example: This is my book.',keyPoints:['A book = un livre.','A pen = un stylo.','This is… = C’est…']),
  Lesson(id:'l22',chapterId:'a2',title:'Days of the week',summary:'Apprendre les jours de la semaine.',content:'The days of the week are Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday. In English, the days begin with a capital letter.',keyPoints:['Monday = lundi.','Friday = vendredi.','Sunday = dimanche.']),

  Lesson(id:'cp1_ml1',chapterId:'cp1_m1',title:'Compter de 0 à 10',summary:'Reconnaître, nommer et compter les quantités de 0 à 10.',content:'Compter consiste à associer un nombre à chaque objet d’une collection. Les nombres de 0 à 10 sont : zéro, un, deux, trois, quatre, cinq, six, sept, huit, neuf et dix. On peut compter des graines, des crayons ou des cailloux en touchant chaque objet une seule fois.',keyPoints:['Compter chaque objet une seule fois.','Le dernier nombre prononcé indique la quantité totale.','Zéro signifie qu’il n’y a aucun objet.']),
  Lesson(id:'cp1_ml2',chapterId:'cp1_m1',title:'Reconnaître les formes',summary:'Identifier le cercle, le carré et le triangle.',content:'Les objets autour de nous ont différentes formes. Un cercle est rond. Un carré possède quatre côtés de même longueur et quatre coins. Un triangle possède trois côtés et trois coins. On peut chercher ces formes dans la classe et à la maison.',keyPoints:['Le cercle est rond.','Le carré a quatre côtés égaux.','Le triangle a trois côtés.']),
  Lesson(id:'cp1_fl1',chapterId:'cp1_f1',title:'Écouter et prononcer des sons',summary:'Écouter attentivement et répéter des mots simples.',content:'Pour bien apprendre à lire, on écoute les mots, on répète les sons et on observe les mouvements de la bouche. On peut commencer par les sons des mots connus : maman, papa, ami, école. Il faut parler clairement et écouter les autres sans les interrompre.',keyPoints:['Écouter avant de répéter.','Prononcer les mots clairement.','Respecter la personne qui parle.']),
  Lesson(id:'cp1_fl2',chapterId:'cp1_f1',title:'Découvrir les lettres',summary:'Reconnaître quelques lettres de l’alphabet.',content:'L’alphabet français comporte 26 lettres. Chaque lettre a un nom et peut représenter un ou plusieurs sons. On commence par reconnaître les lettres de son prénom, puis on apprend progressivement les autres lettres en majuscules et en minuscules.',keyPoints:['L’alphabet comporte 26 lettres.','Les lettres peuvent être écrites en majuscules ou en minuscules.','Le prénom est un bon point de départ pour reconnaître les lettres.']),
  Lesson(id:'cp1_el1',chapterId:'cp1_e1',title:'La famille et l’école',summary:'Nommer les personnes et les lieux de son quotidien.',content:'La famille et l’école font partie de notre environnement proche. Dans la famille, on peut nommer les parents, les enfants et les autres proches. À l’école, on trouve des élèves, un enseignant, une salle de classe et une cour. Chacun doit respecter les autres et prendre soin du matériel.',keyPoints:['Nommer les personnes de son entourage.','Respecter les camarades et les adultes.','Prendre soin du matériel scolaire.']),
  Lesson(id:'cp1_el2',chapterId:'cp1_e1',title:'Propreté et hygiène',summary:'Adopter des gestes simples pour rester propre.',content:'Pour rester propre et en bonne santé, on se lave les mains avec de l’eau propre et du savon, on se brosse les dents et on garde ses vêtements propres. On jette les déchets dans une poubelle et on participe à la propreté de la classe et de la maison.',keyPoints:['Se laver les mains avant de manger et après les toilettes.','Se brosser les dents régulièrement.','Jeter les déchets dans une poubelle.']),
  Lesson(id:'cp1_al1',chapterId:'cp1_a1',title:'Greetings: Hello and goodbye',summary:'Dire bonjour et au revoir en anglais.',content:'En anglais, on peut saluer une personne avec “Hello” ou “Good morning”. Pour prendre congé, on dit “Goodbye” ou “Bye”. Répète les expressions à voix haute avec ton enseignant ou un camarade.',keyPoints:['Hello = Bonjour.','Good morning = Bonjour le matin.','Goodbye = Au revoir.']),
  Lesson(id:'cp1_al2',chapterId:'cp1_a1',title:'Numbers from one to five',summary:'Découvrir les nombres de un à cinq en anglais.',content:'Les cinq premiers nombres en anglais sont one, two, three, four et five. On peut les apprendre en comptant les doigts de la main : one, two, three, four, five. Répète lentement puis essaie de les dire sans regarder.',keyPoints:['One = un.','Two = deux.','Three = trois.','Four = quatre.','Five = cinq.']),

  Lesson(id:'cp2_ml1',chapterId:'cp2_m1',title:'Lire et écrire les nombres jusqu’à 100',summary:'Lire, écrire, décomposer et comparer les nombres jusqu’à 100.',content:'Les nombres servent à compter et à mesurer. Un nombre à deux chiffres comprend des dizaines et des unités. Par exemple, 47 = 4 dizaines et 7 unités. Pour comparer deux nombres, on regarde d’abord les dizaines, puis les unités si les dizaines sont égales. On peut représenter les nombres avec des bâtonnets groupés par dix et des unités isolées.',keyPoints:['Une dizaine vaut dix unités.','47 = 40 + 7.','On compare d’abord les dizaines puis les unités.']),
  Lesson(id:'cp2_ml2',chapterId:'cp2_m1',title:'Addition et soustraction simples',summary:'Calculer des additions et des soustractions sans perdre le sens des opérations.',content:'L’addition sert à réunir des quantités ou à ajouter. Exemple : 23 + 14 = 37. La soustraction sert à enlever ou à chercher une différence. Exemple : 38 − 12 = 26. Pour poser un calcul, on aligne les unités sous les unités et les dizaines sous les dizaines. On peut vérifier une soustraction en ajoutant la différence au nombre enlevé.',keyPoints:['Additionner, c’est réunir ou ajouter.','Soustraire, c’est enlever ou comparer.','Aligner unités et dizaines.']),
  Lesson(id:'cp2_fl1',chapterId:'cp2_f1',title:'Lire un petit texte',summary:'Lire un texte court et retrouver les informations importantes.',content:'Avant de lire, on observe le titre et les images. Ensuite, on lit chaque phrase et on cherche les personnages, le lieu et les actions. Pour répondre à une question, on reprend les informations du texte avec une phrase claire. On peut relire le passage pour vérifier sa réponse.',keyPoints:['Observer le titre.','Repérer qui fait quoi et où.','Relire le texte pour vérifier sa réponse.']),
  Lesson(id:'cp2_fl2',chapterId:'cp2_f1',title:'Construire une phrase simple',summary:'Écrire une phrase avec une majuscule et un point.',content:'Une phrase simple exprime une idée complète. Elle commence par une majuscule et se termine par un point, un point d’interrogation ou un point d’exclamation. Exemple : « Afi joue dans la cour. » On peut trouver le sujet, qui indique de qui on parle, et le verbe, qui exprime l’action ou l’état.',keyPoints:['Commencer par une majuscule.','Exprimer une idée complète.','Terminer par un signe de ponctuation.']),
  Lesson(id:'cp2_el1',chapterId:'cp2_e1',title:'Les parties du corps et les sens',summary:'Nommer quelques parties du corps et leurs fonctions.',content:'Le corps humain comporte la tête, le tronc, les bras et les jambes. Les yeux permettent de voir, les oreilles d’entendre, le nez de sentir, la langue de goûter et la peau de toucher. Il faut protéger son corps et éviter les gestes dangereux.',keyPoints:['Les yeux servent à voir.','Les oreilles servent à entendre.','La peau permet de sentir le contact.']),
  Lesson(id:'cp2_el2',chapterId:'cp2_e1',title:'Protéger sa santé et son environnement',summary:'Appliquer des règles simples d’hygiène et de propreté.',content:'Pour rester en bonne santé, on se lave les mains, on boit de l’eau potable, on mange des aliments propres et on garde les lieux propres. Les déchets doivent être déposés dans une poubelle. Il faut aussi éviter l’eau stagnante et signaler aux adultes les endroits dangereux.',keyPoints:['Se laver les mains avec de l’eau propre et du savon.','Boire de l’eau potable.','Garder la cour et la maison propres.']),
  Lesson(id:'cp2_al1',chapterId:'cp2_a1',title:'Greetings and polite words',summary:'Utiliser des salutations et des mots de politesse en anglais.',content:'In English, we say “Hello” to greet someone and “Goodbye” when leaving. We can say “Please” when asking for something and “Thank you” to show gratitude. Practise these words with a partner.',keyPoints:['Hello = Bonjour.','Please = S’il te plaît.','Thank you = Merci.','Goodbye = Au revoir.']),
  Lesson(id:'cp2_al2',chapterId:'cp2_a1',title:'Classroom objects',summary:'Nommer des objets simples de la classe en anglais.',content:'Here are useful classroom words: book, pen, pencil, ruler, bag and chair. You can say “This is a book” to identify an object. Listen, repeat and point to the correct object in the classroom.',keyPoints:['Book = livre.','Pencil = crayon.','Ruler = règle.','Bag = sac.']),

  Lesson(id:'ce1_ml1',chapterId:'ce1_m1',title:'Les nombres jusqu’à 1 000',summary:'Lire, écrire, décomposer et comparer les nombres jusqu’à 1 000.',content:'Un nombre peut être composé de centaines, de dizaines et d’unités. Dans 326, il y a 3 centaines, 2 dizaines et 6 unités : 326 = 300 + 20 + 6. Pour comparer deux nombres, on compare d’abord les centaines, puis les dizaines et enfin les unités. On peut utiliser les signes <, > et =.',keyPoints:['Une centaine vaut 100 unités.','326 = 300 + 20 + 6.','Comparer les chiffres en commençant par la gauche.']),
  Lesson(id:'ce1_ml2',chapterId:'ce1_m1',title:'Résoudre un problème additif',summary:'Choisir une opération pour résoudre une situation simple.',content:'Pour résoudre un problème, on lit l’énoncé, on repère les informations utiles et on cherche ce que l’on doit trouver. Si l’on réunit deux quantités, on peut faire une addition. Si l’on enlève une quantité ou cherche ce qui reste, on peut faire une soustraction. On écrit le calcul puis une phrase-réponse avec l’unité.',keyPoints:['Lire attentivement la question.','Choisir l’opération adaptée à la situation.','Vérifier le calcul et rédiger une réponse.']),
  Lesson(id:'ce1_fl1',chapterId:'ce1_f1',title:'Le nom et le déterminant',summary:'Repérer le nom et le petit mot qui l’accompagne.',content:'Le nom désigne une personne, un animal, un objet ou une idée. Il peut être accompagné d’un déterminant : le, la, les, un, une, des. Dans « une maison », maison est le nom et une est le déterminant. Le déterminant s’accorde généralement en genre et en nombre avec le nom.',keyPoints:['Le nom désigne une personne, un animal ou une chose.','Le déterminant accompagne le nom.','Exemples : le garçon, une fille, des livres.']),
  Lesson(id:'ce1_fl2',chapterId:'ce1_f1',title:'Lire et raconter un récit',summary:'Comprendre les personnages, le lieu et les étapes d’une histoire.',content:'Un récit raconte des événements. Pour le comprendre, on identifie les personnages, le lieu et le moment de l’histoire. On cherche ensuite ce qui se passe au début, les événements importants et la fin. Pour raconter à son tour, on respecte l’ordre des événements et on utilise des phrases complètes.',keyPoints:['Identifier les personnages et le lieu.','Repérer le début, les événements et la fin.','Raconter dans l’ordre chronologique.']),
  Lesson(id:'ce1_el1',chapterId:'ce1_e1',title:'Les parties d’une plante',summary:'Découvrir les principales parties d’une plante.',content:'Une plante comporte généralement des racines, une tige et des feuilles. Certaines plantes produisent aussi des fleurs, des fruits et des graines. Les racines fixent souvent la plante dans le sol et absorbent l’eau. La tige soutient les feuilles et les fleurs. Les feuilles utilisent la lumière pour fabriquer la matière nécessaire à la croissance.',keyPoints:['Les racines absorbent l’eau et ancrent la plante.','La tige soutient la plante.','Les feuilles captent la lumière.']),
  Lesson(id:'ce1_el2',chapterId:'ce1_e1',title:'Les animaux et leur milieu',summary:'Observer les animaux et les milieux où ils vivent.',content:'Les animaux vivent dans des milieux différents : la forêt, la savane, les mares, les rivières ou les habitations. Ils ont besoin d’eau, de nourriture et d’un abri. Leurs caractéristiques les aident à vivre dans leur milieu. Il faut observer les animaux sans les blesser et respecter leur habitat.',keyPoints:['Les animaux ont besoin de nourriture, d’eau et d’un abri.','Les animaux vivent dans des milieux variés.','Respecter les êtres vivants et leur habitat.']),
  Lesson(id:'ce1_al1',chapterId:'ce1_a1',title:'Introducing yourself',summary:'Dire son nom et son âge en anglais.',content:'To introduce yourself, you can say: “Hello. My name is Kossi. I am eight years old.” To ask a friend’s name, say: “What is your name?” Listen to the answer and practise with a partner. Speak slowly and clearly.',keyPoints:['My name is… = Je m’appelle…','I am eight years old. = J’ai huit ans.','What is your name? = Comment t’appelles-tu ?']),
  Lesson(id:'ce1_al2',chapterId:'ce1_a1',title:'School subjects and classroom instructions',summary:'Nommer quelques matières et comprendre des consignes simples.',content:'Useful school subjects include English, French, mathematics and science. In class, the teacher may say “Listen”, “Repeat”, “Read” or “Write”. Listen carefully and follow the instruction. Practise saying the words and matching them to classroom activities.',keyPoints:['Mathematics = mathématiques.','Listen = écoute.','Read = lis.','Write = écris.']),

  Lesson(id:'ce2_ml1',chapterId:'ce2_m1',title:'Les nombres jusqu’à 10 000',summary:'Lire, écrire, décomposer et comparer les nombres.',content:'Un nombre peut être décomposé en milliers, centaines, dizaines et unités. Par exemple, 4 582 = 4 000 + 500 + 80 + 2. Pour comparer deux nombres, on regarde d’abord le chiffre des milliers, puis celui des centaines, des dizaines et des unités. On range les nombres du plus petit au plus grand ou du plus grand au plus petit.',keyPoints:['1 millier = 1 000 unités.','4 582 = 4 000 + 500 + 80 + 2.','Comparer les chiffres en partant de la gauche.']),
  Lesson(id:'ce2_ml2',chapterId:'ce2_m1',title:'La multiplication et la division simple',summary:'Utiliser la multiplication et le partage en parts égales.',content:'La multiplication permet de calculer rapidement une addition répétée. Par exemple, 4 × 3 signifie 4 groupes de 3, soit 12. La division partage une quantité en parts égales. Si 12 mangues sont partagées entre 3 enfants, chacun reçoit 12 ÷ 3 = 4 mangues. On peut vérifier une division exacte par la multiplication.',keyPoints:['4 × 3 = 12.','12 ÷ 3 = 4.','La multiplication peut vérifier une division exacte.']),
  Lesson(id:'ce2_fl1',chapterId:'ce2_f1',title:'Le présent des verbes usuels',summary:'Conjuguer être, avoir et les verbes en -er au présent.',content:'Au présent, le verbe change selon le sujet. Être : je suis, tu es, il ou elle est, nous sommes, vous êtes, ils ou elles sont. Avoir : j’ai, tu as, il ou elle a, nous avons, vous avez, ils ou elles ont. Pour un verbe régulier en -er comme chanter : je chante, tu chantes, il chante, nous chantons, vous chantez, ils chantent.',keyPoints:['Le sujet indique qui fait l’action.','Être : je suis, nous sommes.','Avoir : j’ai, nous avons.','Chanter : je chante, nous chantons.']),
  Lesson(id:'ce2_fl2',chapterId:'ce2_f1',title:'Écrire un paragraphe simple',summary:'Organiser plusieurs phrases autour d’une même idée.',content:'Un paragraphe est un groupe de phrases qui parlent du même sujet. Pour écrire un petit paragraphe, on choisit une idée, on prépare deux ou trois informations, puis on rédige des phrases dans un ordre logique. On utilise les majuscules, les points et des mots de liaison comme d’abord, ensuite et enfin. On relit pour corriger les accords et l’orthographe.',keyPoints:['Garder une seule idée principale.','Relier les phrases dans un ordre logique.','Relire les majuscules, les points et les accords.']),
  Lesson(id:'ce2_el1',chapterId:'ce2_e1',title:'Les états de l’eau',summary:'Reconnaître l’eau liquide, solide et gazeuse.',content:'L’eau existe sous trois états. À l’état solide, elle forme la glace. À l’état liquide, elle coule et prend la forme du récipient. À l’état gazeux, elle devient vapeur d’eau. La chaleur peut faire fondre la glace ou transformer l’eau liquide en vapeur. Le refroidissement peut transformer la vapeur en petites gouttes ou l’eau en glace.',keyPoints:['Solide : glace.','Liquide : eau qui coule.','Gazeux : vapeur d’eau.','La chaleur et le refroidissement provoquent des changements d’état.']),
  Lesson(id:'ce2_el2',chapterId:'ce2_e1',title:'Protéger notre environnement',summary:'Adopter des gestes simples pour garder le milieu propre.',content:'L’environnement comprend l’air, l’eau, le sol, les plantes, les animaux et les êtres humains. Les déchets jetés dans la nature peuvent salir les lieux et polluer l’eau. Pour protéger notre milieu, nous pouvons utiliser les poubelles, éviter de gaspiller l’eau, planter et entretenir les arbres et garder les espaces communs propres.',keyPoints:['Ne pas jeter les déchets dans la nature.','Économiser l’eau et protéger les arbres.','Garder la maison, l’école et le quartier propres.']),
  Lesson(id:'ce2_al1',chapterId:'ce2_a1',title:'Numbers and colours',summary:'Compter et nommer quelques couleurs en anglais.',content:'Practise numbers from one to twenty: one, two, three, four, five, six, seven, eight, nine, ten. Learn colours: red, blue, green, yellow, black and white. You can say: “I have three blue pencils.” Repeat the words aloud and point to objects with the matching colour.',keyPoints:['One, two, three… ten.','Red = rouge; blue = bleu.','Green = vert; yellow = jaune.']),
  Lesson(id:'ce2_al2',chapterId:'ce2_a1',title:'Talking about my family',summary:'Présenter quelques membres de sa famille.',content:'Use these words: mother, father, brother, sister and family. You can say: “This is my mother” or “I have one brother.” Ask a friend: “Have you got a sister?” Practise with simple sentences and speak clearly.',keyPoints:['Mother = mère; father = père.','Brother = frère; sister = sœur.','This is my family. = Voici ma famille.']),

  Lesson(id:'cm1_ml1',chapterId:'cm1_m1',title:'Découvrir les fractions',summary:'Représenter une partie d’une unité ou d’un ensemble.',content:'Une fraction représente une ou plusieurs parts égales d’une unité. Dans 3/4, le dénominateur 4 indique que l’unité est partagée en quatre parts égales et le numérateur 3 indique que l’on prend trois parts. Une fraction peut être représentée par un dessin, une bande ou un partage concret. Il faut toujours que les parts soient égales.',keyPoints:['Le dénominateur indique le nombre de parts égales.','Le numérateur indique le nombre de parts prises.','Dans 3/4, on prend 3 parts sur 4.']),
  Lesson(id:'cm1_ml2',chapterId:'cm1_m1',title:'Les multiples et la division',summary:'Reconnaître des multiples et effectuer une division simple.',content:'Un multiple d’un nombre est le résultat de sa multiplication par un nombre entier. Les multiples de 5 sont 5, 10, 15, 20, 25… Pour diviser, on cherche combien de fois le diviseur est contenu dans le dividende. Par exemple, 36 ÷ 6 = 6 car 6 × 6 = 36. On vérifie le résultat par la multiplication.',keyPoints:['Les multiples de 5 se terminent par 0 ou 5.','36 ÷ 6 = 6.','La multiplication permet de vérifier une division exacte.']),
  Lesson(id:'cm1_fl1',chapterId:'cm1_f1',title:'Le sujet et le verbe',summary:'Identifier le sujet et accorder le verbe avec lui.',content:'Dans une phrase, le sujet indique de qui ou de quoi on parle. Le verbe exprime généralement une action ou un état. Pour trouver le sujet, on peut poser la question « qui est-ce qui ? » avant le verbe. Le verbe s’accorde avec son sujet : « Les élèves travaillent » ; « L’élève travaille ».',keyPoints:['Le sujet commande l’accord du verbe.','Pour trouver le sujet, poser « qui est-ce qui ? ».','Un sujet pluriel entraîne généralement un verbe au pluriel.']),
  Lesson(id:'cm1_fl2',chapterId:'cm1_f1',title:'Le passé, le présent et le futur',summary:'Situer une action dans le temps.',content:'Le présent indique une action qui se déroule maintenant ou une habitude. Le passé indique une action déjà réalisée. Le futur indique une action qui se déroulera plus tard. Les indicateurs de temps aident à choisir le temps : hier, aujourd’hui, demain, autrefois, bientôt. Il faut garder la cohérence des temps dans un texte.',keyPoints:['Hier : passé.','Aujourd’hui : présent.','Demain : futur.']),
  Lesson(id:'cm1_sl1',chapterId:'cm1_s1',title:'Les organes et leurs fonctions',summary:'Découvrir quelques organes et leur rôle dans le corps.',content:'Le corps humain est composé de plusieurs organes qui travaillent ensemble. Le cœur fait circuler le sang. Les poumons permettent les échanges respiratoires. L’estomac participe à la digestion des aliments. Le cerveau commande et coordonne de nombreuses activités du corps. Une bonne hygiène aide à préserver la santé.',keyPoints:['Le cœur fait circuler le sang.','Les poumons permettent de respirer.','L’estomac participe à la digestion.','Le cerveau coordonne le corps.']),
  Lesson(id:'cm1_sl2',chapterId:'cm1_s1',title:'Solides, liquides et gaz',summary:'Comparer les propriétés des trois états de la matière.',content:'La matière peut se présenter sous forme solide, liquide ou gazeuse. Un solide conserve généralement sa forme. Un liquide s’écoule et prend la forme du récipient. Un gaz se répand et occupe l’espace disponible. L’eau est un exemple de matière que l’on peut observer sous ces trois états : glace, eau liquide et vapeur.',keyPoints:['Un solide conserve sa forme.','Un liquide prend la forme du récipient.','Un gaz se répand dans l’espace disponible.']),
  Lesson(id:'cm1_al1',chapterId:'cm1_a1',title:'Talking about daily routines',summary:'Décrire quelques activités quotidiennes en anglais.',content:'Use simple sentences to talk about your day: “I wake up”, “I go to school”, “I eat lunch” and “I do my homework”. Use “in the morning”, “in the afternoon” and “in the evening” to say when you do an activity. Practise with a partner and pronounce each sentence clearly.',keyPoints:['I wake up. = Je me réveille.','I go to school. = Je vais à l’école.','In the morning = le matin.']),
  Lesson(id:'cm1_al2',chapterId:'cm1_a1',title:'Telling the time',summary:'Demander et donner l’heure en anglais.',content:'To ask the time, say “What time is it?” You can answer “It is seven o’clock” for 7:00. For 7:30, say “It is half past seven”. Practise reading the time on a clock and saying the hours aloud.',keyPoints:['What time is it? = Quelle heure est-il ?','Seven o’clock = sept heures.','Half past seven = sept heures et demie.']),

  Lesson(id:'cm2_ml1',chapterId:'cm2_m1',title:'Additionner et soustraire des nombres décimaux',summary:'Poser et effectuer des opérations avec des nombres décimaux.',content:'Pour additionner ou soustraire des nombres décimaux, on aligne les virgules afin de placer les unités de même rang dans la même colonne. On peut compléter avec des zéros si nécessaire. Exemple : 12,5 + 3,25 = 12,50 + 3,25 = 15,75. On vérifie que le résultat est raisonnable en faisant une estimation.',keyPoints:['Aligner les virgules.','Placer les unités, dixièmes et centièmes dans les bonnes colonnes.','Vérifier le résultat par estimation.']),
  Lesson(id:'cm2_ml2',chapterId:'cm2_m1',title:'Aires et périmètres',summary:'Distinguer le contour d’une figure et sa surface.',content:'Le périmètre mesure la longueur du contour d’une figure. Pour un rectangle, P = 2 × (longueur + largeur). L’aire mesure la surface occupée par la figure. Pour un rectangle, A = longueur × largeur. On exprime le périmètre en unités de longueur, comme le centimètre, et l’aire en unités carrées, comme le centimètre carré.',keyPoints:['Périmètre du rectangle : 2 × (L + l).','Aire du rectangle : L × l.','Ne pas confondre cm et cm².']),
  Lesson(id:'cm2_fl1',chapterId:'cm2_f1',title:'Les accords dans le groupe nominal',summary:'Accorder le déterminant, le nom et l’adjectif.',content:'Dans un groupe nominal, le déterminant, le nom et l’adjectif s’accordent généralement en genre et en nombre. Exemple : un petit garçon, une petite fille, des petits garçons, des petites filles. Pour faire les accords, on repère d’abord le nom principal, puis on vérifie le genre et le nombre des mots qui l’accompagnent.',keyPoints:['Le nom donne le genre et le nombre du groupe.','L’adjectif s’accorde avec le nom.','Exemples : une grande maison, des grandes maisons.']),
  Lesson(id:'cm2_fl2',chapterId:'cm2_f1',title:'Construire un texte organisé',summary:'Rédiger un texte avec introduction, développement et conclusion.',content:'Un texte organisé présente les idées dans un ordre logique. L’introduction annonce le sujet. Le développement explique les idées à l’aide de phrases et d’exemples. La conclusion termine le texte. Les paragraphes séparent les idées et les connecteurs comme d’abord, ensuite, cependant et enfin facilitent la lecture. Il faut relire pour corriger la ponctuation et l’orthographe.',keyPoints:['Une idée principale par paragraphe.','Utiliser des connecteurs logiques.','Relire et corriger le texte.']),
  Lesson(id:'cm2_sl1',chapterId:'cm2_s1',title:'Les sources et les formes d’énergie',summary:'Identifier quelques sources d’énergie et leurs usages.',content:'L’énergie permet de produire un mouvement, de la chaleur ou de la lumière. Le soleil, le vent et l’eau en mouvement sont des sources renouvelables. Le pétrole et le charbon sont des sources non renouvelables qui existent en quantité limitée. Il est important d’économiser l’énergie en éteignant les appareils inutilisés et en privilégiant les solutions moins polluantes.',keyPoints:['Le soleil, le vent et l’eau sont des sources renouvelables.','Le pétrole et le charbon sont non renouvelables.','Économiser l’énergie limite le gaspillage.']),
  Lesson(id:'cm2_sl2',chapterId:'cm2_s1',title:'Prévenir les maladies et protéger la santé',summary:'Comprendre les gestes d’hygiène et de prévention.',content:'La santé dépend notamment de l’hygiène, de l’alimentation, de l’activité physique et de la prévention. Se laver les mains avec de l’eau propre et du savon, boire de l’eau potable, utiliser des latrines propres et dormir suffisamment aident à éviter certaines maladies. En cas de symptômes, il faut demander conseil à un professionnel de santé et éviter l’automédication dangereuse.',keyPoints:['Se laver régulièrement les mains.','Boire de l’eau potable et manger équilibré.','Consulter un professionnel de santé en cas de besoin.']),
  Lesson(id:'cm2_al1',chapterId:'cm2_a1',title:'Asking and giving directions',summary:'Demander et indiquer un chemin en anglais.',content:'To ask for directions, say “Where is the school?” or “How can I get to the market?” Useful directions include “Go straight”, “Turn left” and “Turn right”. You can answer politely: “Go straight and turn left.” Practise giving directions from your classroom to another place.',keyPoints:['Where is the school? = Où est l’école ?','Go straight = Va tout droit.','Turn left / Turn right = Tourne à gauche / à droite.']),
  Lesson(id:'cm2_al2',chapterId:'cm2_a1',title:'Talking about yesterday and tomorrow',summary:'Exprimer des actions passées et des projets simples.',content:'Use “yesterday” to talk about the past and “tomorrow” to talk about the future. Examples: “Yesterday, I played football.” “Tomorrow, I will visit my friend.” Practise saying one thing you did yesterday and one thing you plan to do tomorrow.',keyPoints:['Yesterday = hier.','Tomorrow = demain.','I will visit my friend = Je rendrai visite à mon ami.']),
  Lesson(id:'cinq_ml1',chapterId:'cinq_m1',title:'Les nombres relatifs',summary:'Repérer et comparer les nombres positifs et négatifs.',content:'Un nombre relatif peut être positif, négatif ou nul. Sur une droite graduée, les nombres augmentent de gauche à droite. Ainsi, -2 est supérieur à -5 car -2 est situé plus à droite. La distance à zéro s’appelle la valeur absolue.',keyPoints:['Un nombre positif est supérieur à zéro.','Un nombre négatif est inférieur à zéro.','Sur une droite graduée, le nombre le plus à droite est le plus grand.']),
  Lesson(id:'cinq_ml2',chapterId:'cinq_m1',title:'Fractions : simplifier et comparer',summary:'Comprendre une fraction et reconnaître des fractions équivalentes.',content:'Une fraction représente une ou plusieurs parts d’une unité partagée en parts égales. Le numérateur indique le nombre de parts prises et le dénominateur le nombre total de parts. On peut simplifier une fraction en divisant le numérateur et le dénominateur par un même diviseur non nul.',keyPoints:['Le dénominateur ne peut pas être zéro.','Des fractions équivalentes représentent la même quantité.','Pour simplifier, on divise les deux termes par un même nombre.']),
  Lesson(id:'cinq_fl1',chapterId:'cinq_f1',title:'Comprendre un texte narratif',summary:'Identifier les personnages, le lieu, le temps et les actions.',content:'Un récit raconte une suite d’événements. Pour le comprendre, on repère les personnages, le cadre (lieu et époque), la situation initiale, les événements et la situation finale. Les connecteurs temporels aident à suivre l’ordre des actions.',keyPoints:['Le narrateur raconte l’histoire.','Les personnages réalisent ou subissent les actions.','Les connecteurs comme ensuite, puis et enfin organisent le récit.']),
  Lesson(id:'cinq_fl2',chapterId:'cinq_f1',title:'Les classes grammaticales',summary:'Distinguer nom, déterminant, verbe et adjectif.',content:'Les mots appartiennent à des classes grammaticales. Le nom désigne une personne, un animal, une chose ou une idée. Le déterminant accompagne le nom. Le verbe exprime généralement une action ou un état. L’adjectif apporte une précision sur le nom.',keyPoints:['Le déterminant précède souvent le nom.','Le verbe se conjugue.','L’adjectif précise le nom auquel il se rapporte.']),
  Lesson(id:'cinq_sl1',chapterId:'cinq_s1',title:'Les besoins alimentaires',summary:'Découvrir les groupes d’aliments et leur rôle.',content:'L’organisme a besoin d’une alimentation variée et équilibrée. Certains aliments apportent surtout de l’énergie, d’autres participent à la construction du corps ou à son bon fonctionnement. L’eau est indispensable. Une alimentation équilibrée dépend aussi de l’âge et de l’activité.',keyPoints:['Varier les aliments aide à couvrir les besoins du corps.','L’eau est indispensable à la vie.','Il faut limiter les excès de sucre, de sel et de matières grasses.']),
  Lesson(id:'cinq_sl2',chapterId:'cinq_s1',title:'Hygiène et prévention des maladies',summary:'Adopter des gestes qui protègent la santé.',content:'L’hygiène personnelle et collective réduit les risques de maladie. Il faut se laver les mains avec de l’eau propre et du savon, boire de l’eau potable, conserver les aliments correctement et garder son environnement propre. En cas de symptômes persistants, il faut demander conseil à un professionnel de santé.',keyPoints:['Se laver les mains avant de manger et après les toilettes.','Boire de l’eau potable.','Maintenir les lieux de vie propres et bien aérés.']),
  Lesson(id:'cinq_al1',chapterId:'cinq_a1',title:'Talking about daily routines',summary:'Décrire les activités habituelles en anglais.',content:'Pour parler d’une habitude, on utilise souvent le présent simple. Exemples : I wake up at six. I go to school. Avec he, she ou it, le verbe prend généralement -s à la troisième personne du singulier : She goes to school.',keyPoints:['I get up means « je me lève ».','We use the simple present for habits.','With he or she, the verb usually takes -s.']),
  Lesson(id:'cinq_al2',chapterId:'cinq_a1',title:'Describing people',summary:'Employer des adjectifs simples pour décrire une personne.',content:'Pour décrire une personne, on peut utiliser be et have. Exemples : He is tall. She is kind. He has short hair. Les adjectifs anglais se placent généralement avant le nom et ne prennent pas de marque de pluriel.',keyPoints:['Be sert à décrire une qualité ou un état.','Have permet de parler de ce que quelqu’un possède ou de son apparence.','En anglais, l’adjectif se place avant le nom.']),
  Lesson(id:'quatre_ml1',chapterId:'quatre_m1',title:'Développer une expression',summary:'Utiliser la distributivité simple.',content:'Développer une expression consiste à transformer un produit en somme. La distributivité donne k(a+b)=ka+kb et k(a-b)=ka-kb. Exemple : 3(x+4)=3x+12. On réduit ensuite les termes semblables lorsqu’il y en a.',keyPoints:['Multiplier chaque terme de la parenthèse par le facteur extérieur.','Respecter les signes + et −.','Réduire les termes de même nature.']),
  Lesson(id:'quatre_ml2',chapterId:'quatre_m1',title:'Proportionnalité et pourcentages',summary:'Résoudre des situations de proportionnalité.',content:'Deux grandeurs sont proportionnelles lorsque l’on passe de l’une à l’autre en multipliant toujours par le même nombre, appelé coefficient de proportionnalité. Un pourcentage est une proportion sur 100. Pour calculer 15 % d’une quantité, on multiplie cette quantité par 15/100.',keyPoints:['Un tableau de proportionnalité utilise un même coefficient.','Pour calculer p % de N, effectuer N × p/100.','Vérifier que le résultat est cohérent avec la situation.']),
  Lesson(id:'quatre_fl1',chapterId:'quatre_f1',title:'Construire un texte argumentatif',summary:'Présenter une opinion et la justifier.',content:'Un texte argumentatif défend un point de vue. Il présente une thèse, des arguments et parfois des exemples. Les connecteurs comme d’abord, ensuite, en effet et enfin organisent le raisonnement. Une conclusion rappelle la position défendue.',keyPoints:['La thèse est l’idée que l’on défend.','Un argument explique pourquoi on soutient cette idée.','Un exemple concret renforce un argument.']),
  Lesson(id:'quatre_fl2',chapterId:'quatre_f1',title:'Les propositions dans la phrase',summary:'Distinguer phrase simple et phrase complexe.',content:'Une phrase simple contient généralement un seul verbe conjugué. Une phrase complexe contient plusieurs propositions, souvent organisées autour de plusieurs verbes conjugués. Les propositions peuvent être reliées par coordination, juxtaposition ou subordination.',keyPoints:['Repérer les verbes conjugués aide à compter les propositions.','La coordination utilise notamment mais, ou, et, donc, or, ni, car.','La subordination établit un lien de dépendance entre propositions.']),
  Lesson(id:'quatre_sl1',chapterId:'quatre_s1',title:'La reproduction chez les êtres vivants',summary:'Comprendre la fonction de reproduction.',content:'La reproduction permet aux espèces de se maintenir au fil des générations. Chez de nombreux animaux, la reproduction sexuée fait intervenir des cellules reproductrices mâle et femelle. Leur union forme une cellule-œuf qui se développe ensuite. Les modalités varient selon les espèces.',keyPoints:['La reproduction assure la continuité des espèces.','La reproduction sexuée fait intervenir des cellules reproductrices.','Les étapes du développement diffèrent selon les êtres vivants.']),
  Lesson(id:'quatre_sl2',chapterId:'quatre_s1',title:'Écosystèmes et équilibre du milieu',summary:'Identifier les relations entre êtres vivants et environnement.',content:'Un écosystème comprend un milieu de vie et les êtres vivants qui y interagissent. Les organismes dépendent les uns des autres et des ressources du milieu. La pollution, la destruction des habitats et la surexploitation peuvent perturber cet équilibre. Protéger les habitats contribue à préserver la biodiversité.',keyPoints:['Un écosystème associe un milieu et ses êtres vivants.','Les êtres vivants entretiennent des relations alimentaires et écologiques.','La protection des habitats aide à préserver la biodiversité.']),
  Lesson(id:'quatre_al1',chapterId:'quatre_a1',title:'Talking about past events',summary:'Raconter un événement passé en anglais.',content:'Le prétérit simple sert à parler d’actions terminées dans le passé. Pour de nombreux verbes réguliers, on ajoute -ed : play devient played. Certains verbes sont irréguliers : go devient went. Les expressions yesterday, last week et ago indiquent souvent le passé.',keyPoints:['Le prétérit décrit une action passée et terminée.','Les verbes réguliers prennent généralement -ed.','Les verbes irréguliers ont des formes à mémoriser.']),
  Lesson(id:'quatre_al2',chapterId:'quatre_a1',title:'Expressing future plans',summary:'Parler de projets et de décisions futures.',content:'On peut utiliser be going to pour exprimer un projet ou une intention : I am going to study. Will sert notamment à exprimer une décision spontanée ou une prédiction : I think it will rain. Le contexte permet de choisir la forme appropriée.',keyPoints:['Be going to exprime souvent une intention déjà envisagée.','Will peut exprimer une prédiction ou une décision spontanée.','Le verbe principal reste à la base verbale après will.']),

  Lesson(id:'trois_ml1',chapterId:'trois_m1',title:'Le théorème de Pythagore',summary:'Calculer une longueur dans un triangle rectangle.',content:'Dans un triangle rectangle, le carré de la longueur de l’hypoténuse est égal à la somme des carrés des deux autres côtés. Si ABC est rectangle en A, alors BC² = AB² + AC². Exemple : si AB = 3 cm et AC = 4 cm, alors BC² = 9 + 16 = 25, donc BC = 5 cm. L’hypoténuse est le côté opposé à l’angle droit.',keyPoints:['Repérer d’abord l’angle droit.','L’hypoténuse est le côté le plus long, opposé à l’angle droit.','Écrire l’égalité de Pythagore avant de remplacer par les mesures.']),
  Lesson(id:'trois_ml2',chapterId:'trois_m1',title:'Résoudre une équation du premier degré',summary:'Trouver la valeur inconnue en conservant l’égalité.',content:'Une équation est une égalité qui contient une inconnue, souvent notée x. Pour résoudre 3x + 5 = 20, on soustrait 5 aux deux membres : 3x = 15. Puis on divise les deux membres par 3 : x = 5. On vérifie en remplaçant x par 5 dans l’équation de départ.',keyPoints:['Effectuer la même opération sur les deux membres.','Isoler progressivement l’inconnue.','Vérifier la solution dans l’équation initiale.']),
  Lesson(id:'trois_fl1',chapterId:'trois_f1',title:'Construire un texte argumentatif',summary:'Défendre une opinion avec des arguments et des exemples.',content:'Un texte argumentatif cherche à convaincre ou à faire réfléchir le lecteur. Il présente une thèse, c’est-à-dire le point de vue défendu, puis des arguments organisés et des exemples précis. Les connecteurs comme d’abord, ensuite, en effet, cependant et enfin rendent le raisonnement plus clair. Une conclusion rappelle la position défendue.',keyPoints:['La thèse exprime l’opinion défendue.','Un argument explique pourquoi cette opinion est soutenue.','Un exemple concret renforce un argument.']),
  Lesson(id:'trois_fl2',chapterId:'trois_f1',title:'Les propositions subordonnées',summary:'Distinguer proposition principale et proposition subordonnée.',content:'Une phrase complexe contient plusieurs propositions, généralement organisées autour de plusieurs verbes conjugués. La proposition principale peut fonctionner sans la subordonnée. La subordonnée dépend d’une autre proposition et est souvent introduite par un mot comme que, quand, parce que ou qui. Exemple : « Je pense que tu as raison » : « Je pense » est la principale et « que tu as raison » est la subordonnée.',keyPoints:['Repérer les verbes conjugués pour délimiter les propositions.','La subordonnée dépend d’une principale.','Les mots introducteurs aident à reconnaître la subordination.']),
  Lesson(id:'trois_sl1',chapterId:'trois_s1',title:'Transmission des caractères héréditaires',summary:'Comprendre comment certains caractères se transmettent entre générations.',content:'Les êtres vivants présentent des caractères qui peuvent être transmis des parents aux descendants. L’information héréditaire est portée par l’ADN, organisé notamment en chromosomes dans les cellules. Les descendants ressemblent à leurs parents sans être toujours identiques : la combinaison des informations héréditaires contribue à la diversité des individus. Certains caractères dépendent aussi de l’environnement.',keyPoints:['L’ADN porte une information héréditaire.','Les caractères peuvent être transmis des parents aux descendants.','La diversité résulte de différentes combinaisons et de facteurs environnementaux.']),
  Lesson(id:'trois_sl2',chapterId:'trois_s1',title:'Équilibre et protection des écosystèmes',summary:'Identifier les relations entre les êtres vivants et leur milieu.',content:'Un écosystème comprend un milieu physique et les êtres vivants qui y vivent. Les organismes sont liés par des relations alimentaires et d’autres interactions. La pollution, la destruction des habitats et la surexploitation des ressources peuvent perturber cet équilibre. Protéger les sols, l’eau, les espèces et leurs habitats contribue à préserver la biodiversité.',keyPoints:['Un écosystème associe un milieu et des êtres vivants.','Les êtres vivants interagissent entre eux et avec leur milieu.','La protection des habitats aide à préserver la biodiversité.']),
  Lesson(id:'trois_al1',chapterId:'trois_a1',title:'Talking about past experiences',summary:'Raconter une expérience passée au prétérit.',content:'In English, the simple past is used for completed actions in the past. Regular verbs often take -ed: play becomes played. Some verbs are irregular: go becomes went, see becomes saw. Time expressions such as yesterday, last week and two days ago help locate the action. Example: I visited my grandmother last Sunday.',keyPoints:['Use the simple past for finished past actions.','Regular verbs often end in -ed.','Learn common irregular forms such as go/went and see/saw.']),
  Lesson(id:'trois_al2',chapterId:'trois_a1',title:'Expressing future plans',summary:'Parler de projets avec “be going to”.',content:'Use be going to + base verb to talk about a plan or an intention. Examples: I am going to revise tonight. She is going to visit her aunt. The form of be changes with the subject: am, is or are. For a question, put the form of be before the subject: Are you going to study?',keyPoints:['Structure: subject + am/is/are + going to + verb.','Choose am, is or are according to the subject.','Use this form for intentions and plans.']),

  Lesson(id:'seconde_ml1',chapterId:'seconde_m1',title:'Notion de fonction',summary:'Associer à un nombre une image par une fonction.',content:'Une fonction f associe à chaque nombre x de son ensemble de définition un unique nombre appelé image de x. On note cette image f(x). Exemple : si f(x) = 2x + 3, alors f(4) = 2 × 4 + 3 = 11. Un antécédent de 11 est donc 4. Il faut distinguer l’image, obtenue à partir d’un nombre, et l’antécédent, qui permet de retrouver ce nombre.',keyPoints:['f(x) désigne l’image de x par la fonction f.','Pour calculer une image, remplacer x par la valeur donnée.','Un antécédent de y est un nombre x tel que f(x) = y.']),
  Lesson(id:'seconde_ml2',chapterId:'seconde_m1',title:'Développer et factoriser',summary:'Transformer une expression littérale.',content:'Développer consiste à supprimer des parenthèses en utilisant la distributivité : a(b + c) = ab + ac. Exemple : 3(x + 4) = 3x + 12. Factoriser consiste à écrire une somme sous forme de produit : 3x + 12 = 3(x + 4). Pour vérifier un résultat, on peut développer l’expression factorisée et comparer avec l’expression de départ.',keyPoints:['Développer : a(b + c) = ab + ac.','Factoriser revient à mettre un facteur commun en évidence.','La distributivité permet de passer d’une forme à l’autre.']),
  Lesson(id:'seconde_fl1',chapterId:'seconde_f1',title:'Analyser un texte littéraire',summary:'Étudier le sens, la forme et les effets d’un texte.',content:'L’analyse d’un texte commence par une lecture attentive. On identifie la situation d’énonciation, le thème, le genre et le mouvement du texte. On observe ensuite les procédés d’écriture : champs lexicaux, comparaisons, métaphores, répétitions, rythmes et types de phrases. Chaque remarque doit être appuyée par une citation courte et expliquée : il ne suffit pas de nommer un procédé, il faut montrer son effet sur le lecteur ou le sens.',keyPoints:['Situer le texte et identifier son thème.','Appuyer l’analyse sur des mots ou passages précis.','Expliquer l’effet des procédés d’écriture.']),
  Lesson(id:'seconde_fl2',chapterId:'seconde_f1',title:'Construire un paragraphe argumenté',summary:'Organiser une idée, un argument et un exemple.',content:'Un paragraphe argumenté développe une idée directrice. Il présente d’abord une affirmation claire, puis un argument qui la justifie et un exemple qui l’illustre. Les connecteurs logiques organisent le raisonnement : en effet, de plus, cependant, par conséquent. La phrase de conclusion peut faire le bilan ou préparer l’idée suivante. Le paragraphe doit rester cohérent et répondre au sujet.',keyPoints:['Une idée directrice annonce ce que le paragraphe démontre.','Un argument justifie l’idée et un exemple l’illustre.','Les connecteurs assurent la progression logique.']),
  Lesson(id:'seconde_sl1',chapterId:'seconde_s1',title:'La cellule, unité du vivant',summary:'Reconnaître les structures fondamentales d’une cellule.',content:'La cellule est l’unité de base des êtres vivants. De nombreuses cellules possèdent une membrane qui délimite leur contenu et un cytoplasme. Les cellules eucaryotes possèdent un noyau qui contient l’essentiel de l’information génétique. Les cellules végétales possèdent généralement une paroi et des organites comme les chloroplastes dans les parties vertes. Les organismes peuvent être unicellulaires ou constitués de nombreuses cellules spécialisées.',keyPoints:['La cellule est une unité structurale et fonctionnelle du vivant.','La membrane délimite la cellule.','Les cellules végétales et animales présentent des ressemblances et des différences.']),
  Lesson(id:'seconde_sl2',chapterId:'seconde_s1',title:'Biodiversité et classification',summary:'Décrire la diversité du vivant et comparer les organismes.',content:'La biodiversité désigne la diversité des êtres vivants, de leurs caractères et des écosystèmes. Pour comparer des organismes, on observe des caractères précis et partagés. La classification scientifique regroupe les êtres vivants selon les caractères qu’ils ont en commun et leurs liens de parenté. Elle ne repose pas uniquement sur leur apparence ou leur milieu de vie. Les activités humaines peuvent modifier la biodiversité, ce qui rend sa préservation importante.',keyPoints:['La biodiversité existe à plusieurs niveaux : écosystèmes, espèces et diversité génétique.','La classification s’appuie sur des caractères partagés.','Les activités humaines peuvent menacer certaines espèces et certains milieux.']),
  Lesson(id:'seconde_al1',chapterId:'seconde_a1',title:'Giving opinions and agreeing or disagreeing',summary:'Exprimer un avis et réagir à celui des autres.',content:'To give an opinion, use expressions such as “I think…”, “In my opinion…” or “I believe…”. To agree, say “I agree” or “That is true”. To disagree politely, say “I see your point, but…” or “I am not sure I agree”. Support your opinion with a reason introduced by “because”. Example: “I think reading is useful because it helps us learn new words.”',keyPoints:['I think… = Je pense que…','I agree = Je suis d’accord.','I disagree politely = Je ne suis pas tout à fait d’accord.']),
  Lesson(id:'seconde_al2',chapterId:'seconde_a1',title:'Describing past events and experiences',summary:'Raconter une expérience en utilisant les temps du passé.',content:'The simple past describes a completed action in the past: “We visited the museum yesterday.” The past continuous describes an action in progress at a particular moment: “I was reading when she called.” Time expressions such as last year, two days ago and while help establish the chronology. A clear story usually follows a logical order and uses linking words such as first, then, after that and finally.',keyPoints:['Use the simple past for completed past actions.','Use the past continuous for an action in progress in the past.','Link events with first, then, after that and finally.']),
];

const demoExercises = <Exercise>[
  Exercise(id:'e1',lessonId:'l1',question:'Lequel de ces nombres est un entier ?',options:['3,5','18','2,75'],correctIndex:1,explanation:'18 est un nombre entier car il n’a pas de partie décimale.'),
  Exercise(id:'e2',lessonId:'l2',question:'Dans 7,36, quel chiffre représente les dixièmes ?',options:['7','3','6'],correctIndex:1,explanation:'Le premier chiffre après la virgule représente les dixièmes : ici, c’est 3.'),
  Exercise(id:'e3',lessonId:'l3',question:'Combien font 12,5 + 3,2 ?',options:['15,7','15,2','16,7'],correctIndex:0,explanation:'12,5 + 3,2 = 15,7.'),
  Exercise(id:'e4',lessonId:'l4',question:'Que vaut 6 × 4 ?',options:['20','24','28'],correctIndex:1,explanation:'6 × 4 = 24.'),
  Exercise(id:'e5',lessonId:'l5',question:'1 mètre correspond à combien de centimètres ?',options:['10 cm','100 cm','1 000 cm'],correctIndex:1,explanation:'1 m = 100 cm.'),
  Exercise(id:'e6',lessonId:'l6',question:'Quel est le périmètre d’un carré de côté 5 cm ?',options:['10 cm','15 cm','20 cm'],correctIndex:2,explanation:'P = 4 × 5 = 20 cm.'),
  Exercise(id:'e7',lessonId:'l7',question:'Sur quoi doit-on s’appuyer pour répondre à une question de compréhension ?',options:['Sur le texte','Sur son imagination uniquement','Sur le titre seulement'],correctIndex:0,explanation:'Une réponse doit être justifiée par les informations du texte.'),
  Exercise(id:'e8',lessonId:'l8',question:'Que peut-on utiliser pour comprendre un mot inconnu ?',options:['Le contexte','La couleur du papier','Le nombre de pages'],correctIndex:0,explanation:'Le contexte et le dictionnaire aident à comprendre un mot.'),
  Exercise(id:'e9',lessonId:'l9',question:'Quel signe termine généralement une question ?',options:['.','?','!'],correctIndex:1,explanation:'Une phrase interrogative se termine généralement par un point d’interrogation.'),
  Exercise(id:'e10',lessonId:'l10',question:'Dans « Le garçon court », quel est le verbe ?',options:['Le garçon','court','garçon'],correctIndex:1,explanation:'« court » est le verbe de la phrase.'),
  Exercise(id:'e11',lessonId:'l11',question:'Lequel est un être vivant ?',options:['Une pierre','Une table','Un arbre'],correctIndex:2,explanation:'Un arbre est un végétal vivant.'),
  Exercise(id:'e12',lessonId:'l12',question:'Quel élément est nécessaire au développement d’une plante verte ?',options:['La lumière','Le plastique','Le métal'],correctIndex:0,explanation:'La lumière est nécessaire au développement d’une plante verte.'),
  Exercise(id:'e13',lessonId:'l13',question:'Quel geste aide à limiter la transmission des microbes ?',options:['Ne jamais se laver','Se laver les mains','Boire de l’eau sale'],correctIndex:1,explanation:'Le lavage des mains avec de l’eau propre et du savon réduit la transmission de microbes.'),
  Exercise(id:'e14',lessonId:'l14',question:'Quel organe est associé à la vue ?',options:['Les yeux','Le nez','La peau'],correctIndex:0,explanation:'Les yeux sont les organes de la vue.'),
